//! Runtime data structures used by the tool.
//!
//! These types don't implement `Deserialize` and don't use `Vec`. Instead,
//! they store data in `&'static [T]`, allowing them to be embedded directly
//! into the binary as static values. This avoids any memory allocation or
//! JSON parsing when the tool starts.
//!
//! The actual data is generated by `src/bin/generate_wild4.rs`. That generator
//! reads the original JSON only once during development/build time and produces
//! `src/gen4/generated_wild4.rs`, which contains the fully initialized static
//! data used at runtime.
//!
//! `location` and `species` are now `&'static str` (the JSON stores names
//! directly, there's no more numeric id + separate name-lookup file).
//!
//! The encounter resolution logic (`resolve_grass`, `resolve_water`, etc.)
//! remains exactly the same as before. It still depends on `Conditions`, which
//! are only available at runtime (active swarms, time of day, radar state,
//! and so on), so this logic can't be precomputed by the generator. What the
//! generator removes is the JSON parsing and struct conversion step, while the
//! game logic itself stays unchanged.

use crate::gen4::generated_wild4;
use crate::gen4::honey_tree::{HoneyTreeLocation, get_muchlax_trees};

#[derive(Debug, Clone, Copy)]
pub struct RawEntry {
    pub location: &'static str,
    pub rates: RawRates,
    pub grass: &'static [RawGrassSlot],
    pub swarm: &'static [&'static str],
    pub day: &'static [&'static str],
    pub night: &'static [&'static str],
    pub radar: &'static [&'static str],
    pub form: &'static [u8],
    pub dual_slot: RawDualSlot,
    pub surf: &'static [RawWaterSlot],
    pub old_rod: &'static [RawWaterSlot],
    pub good_rod: &'static [RawWaterSlot],
    pub super_rod: &'static [RawWaterSlot],
}

#[derive(Debug, Clone, Copy)]
pub struct RawRates {
    pub grass: u32,
    pub surf: u32,
    pub old_rod: u32,
    pub good_rod: u32,
    pub super_rod: u32,
}

#[derive(Debug, Clone, Copy)]
pub struct RawGrassSlot {
    pub species: &'static str,
    pub level: u8,
}

#[derive(Debug, Clone, Copy)]
pub struct RawWaterSlot {
    pub species: &'static str,
    pub min_level: u8,
    pub max_level: u8,
}

#[derive(Debug, Clone, Copy)]
pub struct RawDualSlot {
    pub ruby: &'static [&'static str],
    pub sapphire: &'static [&'static str],
    pub emerald: &'static [&'static str],
    pub firered: &'static [&'static str],
    pub leafgreen: &'static [&'static str],
}

#[derive(Debug, Clone, Copy)]
pub struct RawHoneyEntry {
    pub location: &'static str,
    pub normal: &'static [RawWaterSlot],
    pub rare: &'static [RawWaterSlot],
    pub munchlax: &'static [RawWaterSlot],
}

const GRASS_SLOT_RATES: [u32; 12] = [20, 20, 10, 10, 10, 10, 5, 5, 4, 4, 1, 1];
const WATER_SLOT_RATES: [u32; 5] = [60, 30, 5, 4, 1];

const MT_CORONET_B1F_LOCATION: &str = "Mt Coronet Upper B1F";
const FEEBAS_SPECIES: &str = "Feebas";
const FEEBAS_MIN_LEVEL: u8 = 10;
const FEEBAS_MAX_LEVEL: u8 = 20;

const SHELLOS_SPECIES: &str = "Shellos";
const GASTRODON_SPECIES: &str = "Gastrodon";

const FEEBAS_RATE_PERCENT_WHEN_TILE: u32 = 50;

const HONEY_TREE_MAP_IDS: [&str; 21] = [
    "Route 205 (South)",
    "Route 205 (North)",
    "Route 206",
    "Route 207",
    "Route 208",
    "Route 209",
    "Route 210 (South)",
    "Route 210 (North)",
    "Route 211 (East)",
    "Route 212 (North)",
    "Route 212 (South)",
    "Route 213",
    "Route 214",
    "Route 215",
    "Route 218",
    "Route 221",
    "Route 222",
    "Valley Windworks",
    "Eterna Forest",
    "Fuego Ironworks",
    "Floaroma Meadow",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Game {
    Diamond,
    Pearl,
    Platinum,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Method {
    Grass,
    Surf,
    OldRod,
    GoodRod,
    SuperRod,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TimeOfDay {
    Day,
    Night,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DualSlotCartridge {
    Ruby,
    Sapphire,
    Emerald,
    FireRed,
    LeafGreen,
}

#[derive(Debug, Clone, Default)]
pub struct Conditions {
    pub time_of_day: Option<TimeOfDay>,
    pub swarm_active: bool,
    pub radar_active: bool,
    pub dual_slot: Option<DualSlotCartridge>,
    pub feebas_tile: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResolvedEncounter {
    pub species: &'static str,
    pub form: u8,
    pub min_level: u8,
    pub max_level: u8,
    pub rate_percent: u32,
    pub slot: usize,
}

fn encounters_for(game: Game) -> &'static [RawEntry] {
    match game {
        Game::Diamond => generated_wild4::DIAMOND_ENTRIES,
        Game::Pearl => generated_wild4::PEARL_ENTRIES,
        Game::Platinum => generated_wild4::PLATINUM_ENTRIES,
    }
}

fn honey_for(game: Game) -> &'static [RawHoneyEntry] {
    match game {
        Game::Diamond => generated_wild4::DIAMOND_HONEY,
        Game::Pearl => generated_wild4::PEARL_HONEY,
        Game::Platinum => generated_wild4::PLATINUM_HONEY,
    }
}

pub fn get_wild_pokemon(
    game: Game,
    location: &str,
    method: Method,
    cond: &Conditions,
) -> Vec<ResolvedEncounter> {
    get_wild_pokemon_from_entries(encounters_for(game), location, method, cond)
}

pub(crate) fn get_wild_pokemon_from_entries(
    entries: &[RawEntry],
    location: &str,
    method: Method,
    cond: &Conditions,
) -> Vec<ResolvedEncounter> {
    let entry = match entries.iter().find(|e| e.location == location) {
        Some(e) => e,
        None => return vec![],
    };

    match method {
        Method::Grass => resolve_grass(entry, cond),
        Method::Surf => resolve_water(entry.surf, &WATER_SLOT_RATES, entry, false),
        Method::OldRod => resolve_water(entry.old_rod, &WATER_SLOT_RATES, entry, cond.feebas_tile),
        Method::GoodRod => {
            resolve_water(entry.good_rod, &WATER_SLOT_RATES, entry, cond.feebas_tile)
        }
        Method::SuperRod => {
            resolve_water(entry.super_rod, &WATER_SLOT_RATES, entry, cond.feebas_tile)
        }
    }
}

fn resolve_grass(entry: &RawEntry, cond: &Conditions) -> Vec<ResolvedEncounter> {
    let mut species: Vec<&'static str> = entry.grass.iter().map(|s| s.species).collect();
    let levels: Vec<u8> = entry.grass.iter().map(|s| s.level).collect();

    if cond.swarm_active {
        set_slot(&mut species, 0, entry.swarm.first().copied());
        set_slot(&mut species, 1, entry.swarm.get(1).copied());
    }

    if let Some(tod) = cond.time_of_day {
        let arr = match tod {
            TimeOfDay::Day => entry.day,
            TimeOfDay::Night => entry.night,
        };
        set_slot(&mut species, 2, arr.first().copied());
        set_slot(&mut species, 3, arr.get(1).copied());
    }

    if cond.radar_active {
        set_slot(&mut species, 4, entry.radar.first().copied());
        set_slot(&mut species, 5, entry.radar.get(1).copied());
        set_slot(&mut species, 10, entry.radar.get(2).copied());
        set_slot(&mut species, 11, entry.radar.get(3).copied());
    }

    if let Some(cart) = cond.dual_slot {
        let arr: &[&'static str] = match cart {
            DualSlotCartridge::Ruby => entry.dual_slot.ruby,
            DualSlotCartridge::Sapphire => entry.dual_slot.sapphire,
            DualSlotCartridge::Emerald => entry.dual_slot.emerald,
            DualSlotCartridge::FireRed => entry.dual_slot.firered,
            DualSlotCartridge::LeafGreen => entry.dual_slot.leafgreen,
        };
        set_slot(&mut species, 8, arr.first().copied());
        set_slot(&mut species, 9, arr.get(1).copied());
    }

    species
        .iter()
        .zip(levels.iter())
        .zip(GRASS_SLOT_RATES.iter())
        .enumerate()
        .filter(|(_, ((sp, _), _))| !sp.is_empty())
        .map(|(i, ((sp, lvl), rate))| ResolvedEncounter {
            species: sp,
            form: shellos_gastrodon_form(sp, entry),
            min_level: *lvl,
            max_level: *lvl,
            rate_percent: *rate,
            slot: i,
        })
        .collect()
}

fn resolve_water(
    slots: &[RawWaterSlot],
    rates: &[u32; 5],
    entry: &RawEntry,
    feebas_tile: bool,
) -> Vec<ResolvedEncounter> {
    let mut out: Vec<ResolvedEncounter> = slots
        .iter()
        .zip(rates.iter())
        .enumerate()
        .filter(|(_, (s, _))| !s.species.is_empty())
        .map(|(i, (s, rate))| ResolvedEncounter {
            species: s.species,
            form: shellos_gastrodon_form(s.species, entry),
            min_level: s.min_level,
            max_level: s.max_level,
            rate_percent: *rate,
            slot: i,
        })
        .collect();

    if feebas_tile && entry.location == MT_CORONET_B1F_LOCATION {
        out.push(ResolvedEncounter {
            species: FEEBAS_SPECIES,
            form: 0,
            min_level: FEEBAS_MIN_LEVEL,
            max_level: FEEBAS_MAX_LEVEL,
            rate_percent: FEEBAS_RATE_PERCENT_WHEN_TILE,
            slot: 5,
        });
    }

    out
}

fn shellos_gastrodon_form(species: &str, entry: &RawEntry) -> u8 {
    if species == SHELLOS_SPECIES {
        if entry.form.first().copied().unwrap_or(0) == 0 {
            1
        } else {
            0
        }
    } else if species == GASTRODON_SPECIES {
        if entry.form.get(1).copied().unwrap_or(0) == 0 {
            1
        } else {
            0
        }
    } else {
        0
    }
}

fn set_slot(species: &mut [&'static str], idx: usize, value: Option<&'static str>) {
    if let (Some(v), Some(slot)) = (value, species.get_mut(idx)) {
        if !v.is_empty() {
            *slot = v;
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HoneyGroup {
    Normal,
    Rare,
    Munchlax,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HoneyResolvedEncounter {
    pub species: &'static str,
    pub min_level: u8,
    pub max_level: u8,
    pub group: HoneyGroup,
    pub slot: usize,
}

fn tree_id_from_location(location: &str) -> Option<u8> {
    HONEY_TREE_MAP_IDS
        .iter()
        .position(|&id| id == location)
        .map(|i| i as u8)
}

pub fn get_honey_tree_pokemon(
    game: Game,
    location: &str,
    tid: u16,
    sid: u16,
) -> Vec<HoneyResolvedEncounter> {
    get_honey_tree_pokemon_from_entries(honey_for(game), location, tid, sid)
}

pub(crate) fn get_honey_tree_pokemon_from_entries(
    entries: &[RawHoneyEntry],
    location: &str,
    tid: u16,
    sid: u16,
) -> Vec<HoneyResolvedEncounter> {
    let entry = match entries.iter().find(|e| e.location == location) {
        Some(e) => e,
        None => return vec![],
    };

    let munchlax_available = match tree_id_from_location(location) {
        Some(tree_id) => get_muchlax_trees(tid, sid).contains(&HoneyTreeLocation::from(tree_id)),
        None => false,
    };

    let mut seen: Vec<&'static str> = Vec::new();
    let mut out = Vec::new();

    let mut push_group = |slots: &[RawWaterSlot], group: HoneyGroup| {
        for (i, s) in slots.iter().enumerate() {
            if s.species.is_empty() || seen.contains(&s.species) {
                continue;
            }
            seen.push(s.species);
            out.push(HoneyResolvedEncounter {
                species: s.species,
                min_level: s.min_level,
                max_level: s.max_level,
                group,
                slot: i,
            });
        }
    };

    push_group(entry.normal, HoneyGroup::Normal);
    push_group(entry.rare, HoneyGroup::Rare);
    if munchlax_available {
        push_group(entry.munchlax, HoneyGroup::Munchlax);
    }

    out
}

pub fn merge_by_species(mut list: Vec<ResolvedEncounter>) -> Vec<ResolvedEncounter> {
    list.sort_by_key(|e| (e.species, e.form));
    let mut out: Vec<ResolvedEncounter> = Vec::new();
    for enc in list {
        if let Some(last) = out.last_mut() {
            if last.species == enc.species && last.form == enc.form {
                last.rate_percent += enc.rate_percent;
                last.min_level = last.min_level.min(enc.min_level);
                last.max_level = last.max_level.max(enc.max_level);
                continue;
            }
        }
        out.push(enc);
    }
    out
}

