    #[test]
    fn parses_location_0_from_real_sample() {
        let entry = location_0();
        assert_eq!(entry.location, "Canalave City");
        assert_eq!(entry.grass.len(), 12);
        assert_eq!(entry.surf.len(), 5);
        assert_eq!(entry.old_rod[0].species, "Magikarp");
    }

    #[test]
    fn grass_all_zero_species_returns_empty() {
        let entries = [location_0()];
        let result = get_wild_pokemon_from_entries(
            &entries,
            "Canalave City",
            Method::Grass,
            &Conditions::default(),
        );
        assert!(result.is_empty());
    }

