    #[test]
    fn tree_id_from_location_matches_known_list() {
        assert_eq!(tree_id_from_location("Route 205 (South)"), Some(0));
        assert_eq!(tree_id_from_location("Floaroma Meadow"), Some(20));
        assert_eq!(tree_id_from_location("does-not-exist"), None);
    }

    #[test]
    fn merge_by_species_sums_rates_and_widens_level_range() {
        let list = vec![
            ResolvedEncounter {
                species: "Magikarp",
                form: 0,
                min_level: 5,
                max_level: 10,
                rate_percent: 20,
                slot: 0,
            },
            ResolvedEncounter {
                species: "Magikarp",
                form: 0,
                min_level: 3,
                max_level: 8,
                rate_percent: 10,
                slot: 4,
            },
            ResolvedEncounter {
                species: "Gyarados",
                form: 0,
                min_level: 20,
                max_level: 20,
                rate_percent: 1,
                slot: 11,
            },
        ];
        let merged = merge_by_species(list);
        assert_eq!(merged.len(), 2);
        let m_karp = merged.iter().find(|e| e.species == "Magikarp").unwrap();
        assert_eq!(m_karp.rate_percent, 30);
        assert_eq!(m_karp.min_level, 3);
        assert_eq!(m_karp.max_level, 10);
    }
